import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}`),a={name:`architecture.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h1><p>FaultDeck is a Rust workspace. The current implementation ships <strong>six built crates</strong> plus one empty placeholder (<code>faultdeck-protocol</code> — the directory exists but contains no <code>Cargo.toml</code> and is <strong>not</strong> a workspace member yet). The planned toxiproxy backend and scenario YAML DSL from the <a href="/faultdeck/design/mvp-plan.html">MVP plan</a> are not implemented; today&#39;s backend is <code>tc netem</code> + <code>iptables</code>.</p><h2 id="crates" tabindex="-1">Crates <a class="header-anchor" href="#crates" aria-label="Permalink to “Crates”">​</a></h2><table tabindex="0"><thead><tr><th>crate</th><th>binary</th><th>responsibility</th></tr></thead><tbody><tr><td><code>faultdeck-core</code></td><td>—</td><td>shared model: <code>FaultSpec</code> (latency / loss / disconnect), <code>Target</code>, <code>Injection</code>, intrinsic validation (<code>validate_injection</code>), management-network overlap check</td></tr><tr><td><code>faultdeck-netem</code></td><td>—</td><td><code>tc</code> adapter: plans and executes <code>tc qdisc</code>/<code>filter</code> commands, preflight checks, rollback, <code>dry_run</code> executor</td></tr><tr><td><code>faultdeck-agent</code></td><td><code>faultdeck-agent</code></td><td>resident TCP daemon: token auth, request handling, iptables firewall (disconnect), single-active-fault state</td></tr><tr><td><code>faultdeck-coordinator</code></td><td><code>faultdeck-coordinator</code></td><td>multi-target hub: agent registry (register/heartbeat/list), report archive, queued inject/rollback commands</td></tr><tr><td><code>faultdeck-report</code></td><td>—</td><td><code>Scenario</code>, <code>RunReport</code> (JSON/HTML), SHA-256 scenario hash, <code>compare_runs</code> history diff</td></tr><tr><td><code>faultdeck-cli</code></td><td><code>faultdeck</code></td><td>CLI entry: <code>faultdeck remote ping / inject / rollback</code></td></tr><tr><td><code>faultdeck-protocol</code></td><td>—</td><td><em>placeholder, not in workspace</em></td></tr></tbody></table><h2 id="interaction-overview" tabindex="-1">Interaction overview <a class="header-anchor" href="#interaction-overview" aria-label="Permalink to “Interaction overview”">​</a></h2><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> faultdeck CLI                faultdeck-agent                target host</span></span>
<span class="line"><span> ┌──────────────┐   TCP,      ┌──────────────────┐   tc      ┌──────────┐</span></span>
<span class="line"><span> │ remote ping  │──newline──▶ │ token auth       │──qdisc──▶ │  eth0    │</span></span>
<span class="line"><span> │ remote inject│   framed    │ mgmt-network guard│──filter─▶ │ (netem)  │</span></span>
<span class="line"><span> │ remote       │   JSON      │ validate_injection│           └──────────┘</span></span>
<span class="line"><span> │   rollback   │             │                  │  iptables ┌──────────┐</span></span>
<span class="line"><span> └──────────────┘             │ firewall (mangle)│──DROP────▶│ disconnect│</span></span>
<span class="line"><span>                              └──────────────────┘  -t mangle└──────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span> faultdeck-coordinator (default :7001)</span></span>
<span class="line"><span> ┌────────────────────────────────────────────┐</span></span>
<span class="line"><span> │ registry: agents / reports / routes        │◀── framed JSON lines (multi-message</span></span>
<span class="line"><span> │ AgentCommand: register, heartbeat,         │    connections, threaded accept)</span></span>
<span class="line"><span> │   inject, rollback, fetch_report,          │</span></span>
<span class="line"><span> │   list_agents                              │</span></span>
<span class="line"><span> └────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="wire-protocol-cli-↔-agent" tabindex="-1">Wire protocol (CLI ↔ agent) <a class="header-anchor" href="#wire-protocol-cli-↔-agent" aria-label="Permalink to “Wire protocol (CLI ↔ agent)”">​</a></h2><p>One TCP connection per CLI invocation. The client sends a single line; the agent answers with a single JSON line and closes.</p><ul><li>With token: <code>&lt;token&gt; {json}\\n</code> — without: <code>{json}\\n</code></li><li>Request: <code>{&quot;cmd&quot;:&quot;ping&quot;}</code> | <code>{&quot;cmd&quot;:&quot;inject&quot;, ...Injection}</code> | <code>{&quot;cmd&quot;:&quot;rollback&quot;}</code></li><li>Response: <code>{&quot;status&quot;:&quot;ok&quot;,&quot;message&quot;:&quot;...&quot;}</code> | <code>{&quot;status&quot;:&quot;error&quot;,&quot;message&quot;:&quot;...&quot;}</code></li></ul><h2 id="wire-protocol-coordinator" tabindex="-1">Wire protocol (coordinator) <a class="header-anchor" href="#wire-protocol-coordinator" aria-label="Permalink to “Wire protocol (coordinator)”">​</a></h2><p>Long-lived connections, newline-framed JSON lines in both directions (<code>faultdeck-agent::transport</code>). Tagged enums:</p><ul><li><code>AgentCommand</code>: <code>register</code> | <code>heartbeat</code> | <code>inject</code> | <code>rollback</code> | <code>fetch_report</code> | <code>list_agents</code></li><li><code>AgentResponse</code>: <code>ok</code> | <code>error</code> | <code>registered</code> | <code>agents</code> | <code>report</code></li></ul><p>State lives in a <code>Mutex&lt;CoordinatorState&gt;</code>: <code>agents</code> and <code>reports</code> are <code>BTreeMap</code>s, plus a <code>routes</code> map.</p><p><strong>Implementation status:</strong> <code>inject</code>/<code>rollback</code> at the coordinator currently <em>queue</em> the command (the response is <code>queued for {id}</code>, and a report stub is archived under the scenario hash). Dispatch of queued commands to live agent connections is not wired yet; <code>register</code>/<code>heartbeat</code>/<code>list_agents</code>/<code>fetch_report</code> are fully functional in-process.</p><h2 id="failure-handling-in-the-netem-adapter" tabindex="-1">Failure handling in the netem adapter <a class="header-anchor" href="#failure-handling-in-the-netem-adapter" aria-label="Permalink to “Failure handling in the netem adapter”">​</a></h2><ol><li><code>plan()</code> validates and returns the command list without executing.</li><li><code>inject()</code> runs a preflight <code>tc qdisc show</code> — refuses to touch an interface whose root qdisc is not FaultDeck&#39;s <code>100:</code> handle.</li><li>Any leftover FaultDeck root qdisc is cleaned up before applying.</li><li>If any command fails mid-apply, the adapter immediately issues the rollback command.</li><li><code>rollback()</code> deletes the root qdisc; &quot;not found&quot;-style <code>tc</code> errors are tolerated (idempotent).</li></ol><p>Disconnect faults bypass <code>tc</code> entirely — see <a href="/faultdeck/netem-faults.html#disconnect">Netem Faults</a>.</p>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};